-- #6669: a group an app keeps.
--
-- A project's approval rules already name groups (governance.groups in
-- dapp.json). A group may now instead be KEPT BY THE APP: the app sends
-- Homeroom its whole member list, and Homeroom stores it. Nothing here
-- decides anything itself; services/governance.js and the workflow's
-- pr-gate read the current list at decision time, so a person who drops out
-- of the list stops counting and counts again if they return.
--
-- groups_api_token is the app's credential for that one call, generated by
-- the platform at production deploy exactly like storage_api_token. It is
-- staging:private, so a staging container never receives it and unreviewed
-- code cannot change who decides.
ALTER TABLE apps ADD COLUMN IF NOT EXISTS groups_api_token VARCHAR(64);
COMMENT ON COLUMN apps.groups_api_token IS 'staging:private';

CREATE TABLE IF NOT EXISTS app_groups (
  id          SERIAL PRIMARY KEY,
  app_id      INTEGER NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
  key         TEXT    NOT NULL,
  name        TEXT    NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  reported_at TIMESTAMPTZ,
  UNIQUE (app_id, key)
);

CREATE TABLE IF NOT EXISTS app_group_members (
  group_id INTEGER NOT NULL REFERENCES app_groups(id) ON DELETE CASCADE,
  user_id  INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  added_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (group_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_app_group_members_user ON app_group_members (user_id);
